namespace Ordering;

/// <summary>Coordinates product return processing, refund calculation and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnRegistry _returnRegistry = new();
    private readonly RestockLedger _restockLedger = new();
    private readonly RefundJournal _refundJournal = new();

    public string ProcessReturn(Order order, Customer customer)
    {
        var processor = new ReturnProcessor(_returnRegistry, _restockLedger);
        return processor.Process(order, customer);
    }

    public bool IsReturnable(Order order)
    {
        var eligibility = new ReturnEligibility(_returnRegistry);
        return eligibility.IsReturnable(order);
    }

    public decimal ComputeRefund(Order order)
    {
        var calculator = new RefundCalculator(_refundJournal);
        return calculator.Compute(order);
    }

    public void LogRefund(Order order, decimal amount)
    {
        _refundJournal.Log(order, amount);
    }

    public int Restock(Order order)
    {
        return _restockLedger.Restock(order);
    }
}

internal sealed class ReturnRegistry
{
    private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);

    public bool Contains(string reference) => _processedReferences.Contains(reference);

    public void Add(string reference) => _processedReferences.Add(reference);
}

internal sealed class ReturnProcessor
{
    private readonly ReturnRegistry _returnRegistry;
    private readonly RestockLedger _restockLedger;

    public ReturnProcessor(ReturnRegistry returnRegistry, RestockLedger restockLedger)
    {
        _returnRegistry = returnRegistry;
        _restockLedger = restockLedger;
    }

    public string Process(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_returnRegistry.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";
            _restockLedger.Record(line.Sku, line.Quantity);
        }

        if (_restockLedger.SkuCount == 0)
            return "no returnable lines";

        _returnRegistry.Add(order.Reference);
        return "accepted";
    }
}

internal sealed class ReturnEligibility
{
    private readonly ReturnRegistry _returnRegistry;

    public ReturnEligibility(ReturnRegistry returnRegistry)
    {
        _returnRegistry = returnRegistry;
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_returnRegistry.Contains(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                return true;
        }

        return false;
    }
}

internal sealed class RefundCalculator
{
    private const decimal UnitRefund = 5m;
    private readonly RefundJournal _refundJournal;

    public RefundCalculator(RefundJournal refundJournal)
    {
        _refundJournal = refundJournal;
    }

    public decimal Compute(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            refund += CalculateLineRefund(line.Quantity);
        }

        if (_refundJournal.EntryCount > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;
        return refund < 0m ? 0m : refund;
    }

    private static decimal CalculateLineRefund(int quantity)
    {
        if (quantity > 50)
            return quantity * UnitRefund * 0.9m;
        if (quantity > 10)
            return quantity * UnitRefund * 0.95m;
        if (quantity > 1)
            return quantity * UnitRefund;
        return UnitRefund;
    }
}

internal sealed class RefundJournal
{
    private readonly List<string> _entries = new();

    public int EntryCount => _entries.Count;

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;

        if (_entries.Count == 0 || amount > 100m)
            _entries.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _entries.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _entries.Add($"{order.Reference}:mid:{amount}");
        else
            _entries.Add($"{order.Reference}:small:{amount}");

        if (_entries.Count > 500 && amount > 1000m)
            _entries.Add($"{order.Reference}:flag");
    }
}

internal sealed class RestockLedger
{
    private readonly Dictionary<string, int> _quantitiesBySku = new(StringComparer.Ordinal);

    public int SkuCount => _quantitiesBySku.Count;

    public void Record(string sku, int quantity)
    {
        _quantitiesBySku[sku] = _quantitiesBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;

            if (_quantitiesBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _quantitiesBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _quantitiesBySku[sku] = line.Quantity / 2;
            }
            else if (line.Quantity > 0)
            {
                _quantitiesBySku[sku] = line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }
}
